package clusterdata.datatypes;

import java.io.Serializable;

public class TaskEvent implements Serializable {
    private static final long serialVersionUID = 1L;

    public long timestamp;
    public String missingInfo;
    public long jobId;
    public long taskIndex;
    public Long machineId;
    public int eventType;
    public String userName;
    public int schedulingClass;
    public int priority;
    public double cpuRequest;
    public double memoryRequest;
    public double diskRequest;
    public int differentMachineConstraint;

    public TaskEvent() {}

    public TaskEvent(long timestamp, String missingInfo, long jobId, long taskIndex,
                     Long machineId, int eventType, String userName, int schedulingClass,
                     int priority, double cpuRequest, double memoryRequest,
                     double diskRequest, int differentMachineConstraint) {
        this.timestamp = timestamp;
        this.missingInfo = missingInfo;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.machineId = machineId;
        this.eventType = eventType;
        this.userName = userName;
        this.schedulingClass = schedulingClass;
        this.priority = priority;
        this.cpuRequest = cpuRequest;
        this.memoryRequest = memoryRequest;
        this.diskRequest = diskRequest;
        this.differentMachineConstraint = differentMachineConstraint;
    }

    @Override
    public String toString() {
        return "TaskEvent{" +
                "timestamp=" + timestamp +
                ", jobId=" + jobId +
                ", taskIndex=" + taskIndex +
                ", eventType=" + eventType +
                '}';
    }
}

