                .connect(jobTerminations.keyBy(event -> event.jobId))
                .process(new OutputOnJobTermination());

        // Write output to file
        if (out == null) {
            results.sinkTo(
                StreamingFileSink.<String>forRowFormat(
                    new Path(outputPath),
                    new org.apache.flink.api.common.serialization.SimpleStringEncoder<String>("UTF-8")
                )
                .withRollingPolicy(OnCheckpointRollingPolicy.build())
                .build()
            );
        } else {
            results.addSink(sinkOrTest(null));
        }

        env.execute("LongestSessionPerJob");
    }

    // Process task submit events to identify stages and count tasks per stage
    public static class SessionProcessor extends KeyedProcessFunction<Long, TaskEvent, Tuple2<Long, Integer>> {

        private transient ValueState<Long> lastSubmitTime;
        private transient ValueState<Integer> currentStageCount;

        @Override
        public void open(Configuration parameters) {
            lastSubmitTime = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("lastSubmitTime", Long.class));
            currentStageCount = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("currentStageCount", Integer.class));
        }

        @Override
        public void processElement(TaskEvent event, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            Long lastTime = lastSubmitTime.value();
            Integer count = currentStageCount.value();

            if (lastTime == null) {
                // First submit event for this job
                lastSubmitTime.update(event.timestamp);
                currentStageCount.update(1);
            } else {
                long gap = event.timestamp - lastTime;

                if (gap > SESSION_GAP_MICROS) {
                    // Session ended, emit the count and start new session
                    out.collect(new Tuple2<>(event.jobId, count));
                    currentStageCount.update(1);
                } else {
                    // Same session, increment count
                    currentStageCount.update(count + 1);
                }
                lastSubmitTime.update(event.timestamp);
            }
        }
    }

    // Track the maximum stage count for each job
    public static class MaxStageProcessor extends KeyedProcessFunction<Long, Tuple2<Long, Integer>, Tuple2<Long, Integer>> {

        private transient ValueState<Integer> maxCount;

        @Override
        public void open(Configuration parameters) {
            maxCount = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("maxCount", Integer.class));
        }

        @Override
        public void processElement(Tuple2<Long, Integer> value, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            Integer currentMax = maxCount.value();

            if (currentMax == null || value.f1 > currentMax) {
                maxCount.update(value.f1);
                out.collect(value);
            }
        }
    }

    // Output the result only when job terminates
    public static class OutputOnJobTermination extends CoProcessFunction<Tuple2<Long, Integer>, JobEvent, String> {

        private transient ValueState<Integer> maxStageCount;
        private transient ValueState<Boolean> jobTerminated;

        @Override
        public void open(Configuration parameters) {
            maxStageCount = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("maxStageCount", Integer.class));
            jobTerminated = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("jobTerminated", Boolean.class));
        }

        @Override
        public void processElement1(Tuple2<Long, Integer> value, Context ctx, Collector<String> out) throws Exception {
            // Update max stage count
            maxStageCount.update(value.f1);

            // If job already terminated, output result
            Boolean terminated = jobTerminated.value();
            if (terminated != null && terminated) {
                out.collect("(" + value.f0 + "," + value.f1 + ")");
            }
        }

        @Override
        public void processElement2(JobEvent event, Context ctx, Collector<String> out) throws Exception {
            // Mark job as terminated
            jobTerminated.update(true);

            // If we have max count, output result
            Integer count = maxStageCount.value();
            if (count != null) {
                out.collect("(" + event.jobId + "," + count + ")");
            }
        }
    }
}

